// static
bool StructTraits<::ash::libassistant::mojom::AssistantFeedback::DataView, ::ash::libassistant::mojom::AssistantFeedbackPtr>::Read(
    ::ash::libassistant::mojom::AssistantFeedback::DataView input,
    ::ash::libassistant::mojom::AssistantFeedbackPtr* output) {
  bool success = true;
  ::ash::libassistant::mojom::AssistantFeedbackPtr result(::ash::libassistant::mojom::AssistantFeedback::New());
  
      if (success && !input.ReadDescription(&result->description))
        success = false;
      if (success)
        result->assistant_debug_info_allowed = input.assistant_debug_info_allowed();
      if (success && !input.ReadScreenshotPng(&result->screenshot_png))
        success = false;
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::ash::libassistant::mojom::DeviceSetting::DataView, ::ash::libassistant::mojom::DeviceSettingPtr>::Read(
    ::ash::libassistant::mojom::DeviceSetting::DataView input,
    ::ash::libassistant::mojom::DeviceSettingPtr* output) {
  bool success = true;
  ::ash::libassistant::mojom::DeviceSettingPtr result(::ash::libassistant::mojom::DeviceSetting::New());
  
      if (success && !input.ReadSettingId(&result->setting_id))
        success = false;
      if (success)
        result->is_supported = input.is_supported();
  *output = std::move(result);
  return success;
}

